<?php $st=$pdo->prepare("SELECT * FROM colleges WHERE id=?");$st->execute([(int)($_GET['id']??0)]);$c=$st->fetch(PDO::FETCH_ASSOC);if(!$c):?><div class="wrap section"><h2>Institution not found</h2></div><?php else: $gs=$pdo->prepare("SELECT * FROM gallery WHERE college_id=? ORDER BY sort_order,id");$gs->execute([$c['id']]);$images=$gs->fetchAll(PDO::FETCH_ASSOC);?><section class="wrap section"><div class="profile-head"><div><span class="eyebrow"><?=h($c['kind'])?></span><h1><?=h($c['name'])?></h1><p><?=h($c['city'])?></p><p><?=h($c['description'])?></p><a class="btn btn-primary" href="<?=url('admission',['college_id'=>$c['id']])?>">Enquire / Apply</a></div><div class="slider"><div class="slide-placeholder" id="slideBox"><span id="slideCaption">Campus view · 1/<?=max(5,count($images))?></span></div><button class="slide-prev" onclick="moveSlide(-1)">‹</button><button class="slide-next" onclick="moveSlide(1)">›</button><div class="dots" id="slideDots"></div></div></div><div class="tabs"><span>Overview</span><span>Courses & Fees</span><span>Admissions</span><span>Facilities</span><span>Gallery</span></div><div class="panel"><h2>About <?=h($c['name'])?></h2><p><?=h($c['description'])?> This is a demo profile; add verified institution facts and official sources before publishing.</p><h3>Popular courses</h3><p>B.Tech · MBA · BCA · B.Com</p></div></section><script>const slideLabels=<?=json_encode(array_map(fn($g)=>$g['caption']?:'Campus image',$images)?:['Campus view','Academic block','Library','Classroom','Facilities'])?>;let si=0;function renderSlide(){document.getElementById('slideCaption').textContent=(slideLabels[si]||'Campus view')+' · '+(si+1)+'/'+Math.max(5,slideLabels.length);document.getElementById('slideDots').innerHTML=Array.from({length:Math.max(5,slideLabels.length)},(_,i)=>'<button class="'+(i===si?'active':'')+'" onclick="si='+i+';renderSlide()"></button>').join('')}function moveSlide(d){si=(si+d+Math.max(5,slideLabels.length))%Math.max(5,slideLabels.length);renderSlide()}renderSlide();setInterval(()=>moveSlide(1),3500);</script><?php endif;?>